begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(37);
insert into auth.users(id,email)values('a1100000-0000-4000-8000-000000000001','change-admin@test.local'),('a1100000-0000-4000-8000-000000000002','change-manager@test.local'),('a1100000-0000-4000-8000-000000000003','change-member@test.local'),('a1100000-0000-4000-8000-000000000004','change-stake@test.local'),('a1100000-0000-4000-8000-000000000005','change-false@test.local'),('a1100000-0000-4000-8000-000000000006','change-out@test.local');insert into profiles(id,email,full_name)select id,email,email from auth.users where id::text like'a1100000-%';insert into organizations(id,name,created_by)values('a1200000-0000-4000-8000-000000000001','Change Org','a1100000-0000-4000-8000-000000000001'),('a1200000-0000-4000-8000-000000000002','Other Org','a1100000-0000-4000-8000-000000000006');insert into organization_members(organization_id,user_id,role,status)values('a1200000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000001','Administrator','Active'),('a1200000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000002','Member','Active'),('a1200000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000003','Member','Active'),('a1200000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000004','Member','Active'),('a1200000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000005','Member','Active'),('a1200000-0000-4000-8000-000000000002','a1100000-0000-4000-8000-000000000006','Administrator','Active');insert into projects(id,organization_id,name,business_objective,project_manager_id,sponsor_name,lifecycle_phase,status,start_date,target_completion_date,overall_health,scope_health,schedule_health,budget_health,resource_health,risk_health,created_by)values('a1300000-0000-4000-8000-000000000001','a1200000-0000-4000-8000-000000000001','Change Project','Test','a1100000-0000-4000-8000-000000000002','Sponsor','Execution','Active',current_date+10,current_date+100,'Green','Green','Green','Green','Green','Green','a1100000-0000-4000-8000-000000000001');insert into project_members(id,project_id,user_id,access_level)values('a1400000-0000-4000-8000-000000000001','a1300000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000002','Project Manager'),('a1400000-0000-4000-8000-000000000002','a1300000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000003','Project Member'),('a1400000-0000-4000-8000-000000000003','a1300000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000004','Stakeholder'),('a1400000-0000-4000-8000-000000000004','a1300000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000005','Project Manager');select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','a1100000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$select create_project_change_request('a1300000-0000-4000-8000-000000000001','  Scope change  ','Description','Reason','Scope','Steering committee',current_date,null,null,null,null,null,null,null)$$,'Administrator creates Draft');select ok((select status='Draft'and created_by='a1100000-0000-4000-8000-000000000001'and last_edited_by=created_by from project_change_requests),'Trusted Draft audit');select is((select title from project_change_requests),'Scope change','Text normalized');select throws_ok($$select create_project_change_request('a1300000-0000-4000-8000-000000000001','Future','D','R','Scope','Requester',current_date+1,null,null,null,null,null,null,null)$$,'22023','Requested date cannot be in the future.','Future date denied');select throws_ok($$select submit_project_change_request((select id from project_change_requests),true)$$,'22023','Complete the impact assessment before submission.','Incomplete submission denied');
select set_config('request.jwt.claim.sub','a1100000-0000-4000-8000-000000000003',true);select is((select count(*)from project_change_requests),0::bigint,'Member cannot discover Draft');select throws_ok($$select submit_project_change_request((select id from project_change_requests),true)$$,'42501','Change Request operation is not permitted.','Member mutation denied');select set_config('request.jwt.claim.sub','a1100000-0000-4000-8000-000000000005',true);select throws_ok($$select create_project_change_request('a1300000-0000-4000-8000-000000000001','X','D','R','Scope','R',current_date,null,null,null,null,null,null,null)$$,'42501','Change Request operation is not permitted.','Arbitrary manager label denied');
select set_config('request.jwt.claim.sub','a1100000-0000-4000-8000-000000000002',true);select is((select count(*)from project_change_requests),1::bigint,'Actual manager sees Draft');select lives_ok($$select update_project_change_request_draft((select id from project_change_requests),'Scope change','Updated','Reason','Scope','Customer',current_date,'Scope','Schedule','Budget','Resources','Quality','Risk','Approve')$$,'Manager completes assessment');select ok((select last_edited_by='a1100000-0000-4000-8000-000000000002'and quality_impact='Quality'from project_change_requests),'Editor and quality impact stored');select throws_ok($$select submit_project_change_request((select id from project_change_requests),false)$$,'22023','Submission confirmation is required.','Submission confirmation required');select lives_ok($$select submit_project_change_request((select id from project_change_requests),true)$$,'Draft submitted');select set_config('request.jwt.claim.sub','a1100000-0000-4000-8000-000000000003',true);select is((select count(*)from project_change_requests),1::bigint,'Member reads formal request');
select set_config('request.jwt.claim.sub','a1100000-0000-4000-8000-000000000002',true);select throws_ok($$select approve_project_change_request((select id from project_change_requests),'Approved','a1400000-0000-4000-8000-000000000003',current_date,false)$$,'22023','Approval confirmation and notes are required.','Approval confirmation required');select throws_ok($$select approve_project_change_request((select id from project_change_requests),'Approved','a1400000-0000-4000-8000-000000000003',current_date,true)$$,'23514','The implementation owner is not eligible.','Stakeholder owner denied');select throws_ok($$select approve_project_change_request((select id from project_change_requests),'Approved','a1400000-0000-4000-8000-000000000002',current_date-1,true)$$,'22023','Implementation target date cannot precede approval.','Past target denied');select lives_ok($$select approve_project_change_request((select id from project_change_requests),'Approved','a1400000-0000-4000-8000-000000000002',current_date+10,true)$$,'Manager approves');select ok((select status='Approved'and decided_by='a1100000-0000-4000-8000-000000000002'and implementation_plan_updated_by=decided_by from project_change_requests),'Decision and plan audit trusted');select lives_ok($$select update_change_request_implementation_plan((select id from project_change_requests),'a1400000-0000-4000-8000-000000000001',current_date+12)$$,'Implementation plan narrowly updated');select throws_ok($$select start_change_request_implementation((select id from project_change_requests),false)$$,'22023','Implementation start confirmation is required.','Start confirmation required');select lives_ok($$select start_change_request_implementation((select id from project_change_requests),true)$$,'Implementation starts');select throws_ok($$select complete_project_change_request((select id from project_change_requests),' ',true)$$,'22023','Implementation confirmation and outcome notes are required.','Outcome notes required');select lives_ok($$select complete_project_change_request((select id from project_change_requests),'Delivered safely',true)$$,'Implemented outcome');select throws_ok($$select complete_project_change_request((select id from project_change_requests),'Again',true)$$,'42501','Change Request operation is not permitted.','Terminal immutable');
select set_config('request.jwt.claim.sub','a1100000-0000-4000-8000-000000000001',true);select lives_ok($$select create_project_change_request('a1300000-0000-4000-8000-000000000001','Reject','D','R','Risk','Sponsor',current_date,'S','S','B','R','Q','R','Reject')$$,'Rejection Draft created');select lives_ok($$select submit_project_change_request((select id from project_change_requests where title='Reject'),true)$$,'Rejection submitted');select lives_ok($$select reject_project_change_request((select id from project_change_requests where title='Reject'),'Not justified',true)$$,'Rejected with audit');select lives_ok($$select create_project_change_request('a1300000-0000-4000-8000-000000000001','Withdraw','D','R','Other','Sponsor',current_date,null,null,null,null,null,null,null)$$,'Withdrawal Draft created');select lives_ok($$select withdraw_project_change_request((select id from project_change_requests where title='Withdraw'),'No longer needed',true)$$,'Draft withdrawn');select lives_ok($$select create_project_change_request('a1300000-0000-4000-8000-000000000001','Abandon','D','R','Technical','Sponsor',current_date,'S','S','B','R','Q','R','Approve')$$,'Not Implemented Draft created');select lives_ok($$select submit_project_change_request((select id from project_change_requests where title='Abandon'),true)$$,'Not Implemented submitted');select lives_ok($$select approve_project_change_request((select id from project_change_requests where title='Abandon'),'Approved','a1400000-0000-4000-8000-000000000002',current_date+2,true)$$,'Not Implemented approved');select lives_ok($$select mark_project_change_request_not_implemented((select id from project_change_requests where title='Abandon'),'Funding removed',true)$$,'Approved becomes Not Implemented');
select set_config('request.jwt.claim.sub','a1100000-0000-4000-8000-000000000006',true);select is((select count(*)from project_change_requests),0::bigint,'Cross organization denied');select throws_ok($$insert into project_change_requests(project_id,title,description,reason,category,requester_name,requested_date,created_by,last_edited_by)values('a1300000-0000-4000-8000-000000000001','X','D','R','Scope','R',current_date,'a1100000-0000-4000-8000-000000000006','a1100000-0000-4000-8000-000000000006')$$,'42501','permission denied for table project_change_requests','Direct insert and audit injection denied');select ok(not has_table_privilege('authenticated','project_change_requests','DELETE'),'No delete privilege');select*from finish();rollback;
